module ot_qfd_land #(
    parameter integer W     = 16,
    parameter integer D     = 4,                       // ring depth, power of two >= 2 (window D x T)
    parameter integer FIRST = 0,                       // 1: n = 1 lane, the landing carries the hop-0 gate (ck_s, en)
    parameter integer AW    = (D <= 2) ? 1 : $clog2(D)
) (
    input  wire         ckf,      // FIRST 0: lane forwarded clock (last station ck_o); FIRST 1: source block root
    input  wire         ea,       // FIRST 0: lane epoch (last station eb); FIRST 1: source released reset
    input  wire [W-1:0] i,
    input  wire         ck,       // receiving block root
    input  wire         rs,       // receiving block regional reset, active low (async assert, release on ck)
    input  wire [AW:0]  k,        // K strap (identity strap from the instance's own tie cells)
    output reg  [W-1:0] o,
    output reg          fault
);
    wire wck, we;                 // ring write clock / write-side epoch
    generate if (FIRST != 0) begin : g_hop0
        // QK-LANDEN 10-19 (coordinator, Q.STA.LAND600.3 option (b); the ROOT-RST rule: reset-derived inputs are registered
        // at the face, never timed as exceptions): en (the source's released reset) is registered on ck_s (= ckf here)
        // BEFORE the clock gate.  One face flop: asynchronous clear by en (assert immediate, also with every clock
        // stopped), release on the next ck_s edge.  The ICG enable and the ring's write epoch are this flop, never the
        // input port (closed views: en -> ICG combinational, native capture 351-429 ps > 190).
        // Calendar: the write epoch moves from source edge G to G + 1 (first gated edge G + 2; the source word launched
        // at G, still its reset value, is not written).  Every later word is written on the SAME physical edge as before
        // (same ring age E); only its slot index is one lower, so the die strap is K = (E + (G + 1) - R0) mod 8
        // (tools/qwen_split/lane_groups.py HOP0_EN_REG, reset_calendar_audit.py finalize_model).
        (* keep = "true", dont_touch = "true" *) reg en_q;
`ifdef OT_QFD_LAND_MUT_ENCOMB
        always @(*) en_q = ea;                                     // bench mutant: en unregistered (the closed-view form)
`else
        always @(posedge ckf or negedge ea)
            if (!ea) en_q <= 1'b0; else en_q <= 1'b1;
`endif
        ot_qfd_fwd0 u_fwd0 (.ck(ckf), .en(en_q), .cko(wck));
        assign we = en_q;         // en_q rises after source edge G + 1, half a period before the first gated edge G + 2
    end else begin : g_lane
        assign wck = ckf;
        assign we = ea;
    end endgenerate
    reg [W-1:0] bank [0:D-1];
    reg [AW:0]  epo  [0:D-1];
    wire [D-1:0] vld;
    reg [AW:0]  wc, rc;
    reg         warm;
    // ------------------------------------------------------------------ write side (wck), cleared by the lane epoch
    always @(posedge wck or negedge we)
        if (!we) wc <= {(AW + 1){1'b0}};
        else     wc <= wc + 1'b1;
    genvar s;
    generate for (s = 0; s < D; s = s + 1) begin : g_slot
        always @(posedge wck) if (wc[AW-1:0] == s) begin bank[s] <= i; epo[s] <= wc; end
        reg v;                                                     // slot written since the lane epoch began
        always @(posedge wck or negedge we)
            if (!we) v <= 1'b0;
`ifdef OT_QFD_LAND_MUT_VLD
            else v <= 1'b1;                                        // bench mutant: every slot valid at once
`else
            else if (wc[AW-1:0] == s) v <= 1'b1;
`endif
        assign vld[s] = v;
    end endgenerate
    // ------------------------------------------------------------------ read side (ck)
`ifdef OT_QFD_LAND_MUT_SEL
    wire [AW:0] exp_ = rc - k + 1'b1;                              // bench mutant: read slot one late
`else
    wire [AW:0] exp_ = rc - k;
`endif
    wire [AW-1:0] rs_ = exp_[AW-1:0];
    always @(posedge ck or negedge rs)
        if (!rs) begin rc <= {(AW + 1){1'b0}}; warm <= 1'b0; fault <= 1'b0; end
        else begin
            rc <= rc + 1'b1;
            if (rc == k - 1'b1) warm <= 1'b1;
            if (warm && vld[rs_] && epo[rs_] != exp_) fault <= 1'b1;
        end
`ifdef OT_QFD_LAND_MUT_NAIVE
    always @(posedge ck) o <= warm ? i : {W{1'b0}};                // bench mutant: retime register only, no ring
`else
    always @(posedge ck) o <= (warm && vld[rs_]) ? bank[rs_] : {W{1'b0}};
`endif
`ifndef SYNTHESIS
    initial if (D < 2 || (D & (D - 1)) != 0) $fatal(1, "ot_qfd_land: D must be a power of two >= 2");
`endif
endmodule

module qkd_d2d_cal_seq_pin_bc #(parameter integer GO_OFS = 0, parameter [20*36-1:0] START_ADJ = '0,
                                parameter integer EP_SKEW = 3, parameter integer MUT = 0) (
    input  wire        ck, rst_n, reload, epoch_go, halt,
    input  wire        bcfg_tx_we, bcfg_rx_we,
    input  wire [5:0]  bcfg_addr,
    input  wire [31:0] bcfg_data,
    output reg         cfg_tx_we, cfg_rx_we,
    output reg  [5:0]  cfg_addr,
    output reg  [31:0] cfg_data,
    output reg         cal_start, cal_seg, cal_ready, running,
    output reg  [5:0]  layer,
    output reg         adm_done, tok_start,
    output reg         fault);
    `include "d2d_cal_image_mu.svh"
    initial if (EP_SKEW < 2) $error("EP_SKEW >= 2 needed (input capture + output stage)");
    // ---- input capture (as qkd_d2d_cal_seq_pin) + the boot cfg pin registers
    reg [1:0] release_q;
    reg reload_q, epoch_go_q, halt_q;
    reg b_tx_q, b_rx_q;
    reg [5:0] b_addr_q;
    reg [31:0] b_data_q;
    always @(posedge ck or negedge rst_n) begin
        if (!rst_n) begin
            release_q <= 0; reload_q <= 0; epoch_go_q <= 0; halt_q <= 1;
            b_tx_q <= 0; b_rx_q <= 0; b_addr_q <= 0; b_data_q <= 0;
        end else begin
            release_q <= {release_q[0], 1'b1};
            reload_q <= reload; epoch_go_q <= epoch_go; halt_q <= halt;
            b_tx_q <= bcfg_tx_we; b_rx_q <= bcfg_rx_we; b_addr_q <= bcfg_addr; b_data_q <= bcfg_data;
        end
    end
    wire rl = release_q[1];
    wire s_tx, s_rx, s_cs, s_seg, s_rdy, s_run, s_adm, s_tok, s_fault;
    wire [5:0] s_addr, s_layer;
    wire [31:0] s_data;
    qkd_d2d_cal_seq #(.GO_OFS(GO_OFS), .START_ADJ(START_ADJ), .EP_SKEW(EP_SKEW - 2)) u_seq (
        .ck(ck), .rst_n(rl), .reload(reload_q), .tok_go(1'b0), .epoch_go(epoch_go_q), .halt(halt_q),
        .cfg_tx_we(s_tx), .cfg_rx_we(s_rx), .cfg_addr(s_addr), .cfg_data(s_data),
        .cal_start(s_cs), .cal_seg(s_seg), .cal_ready(s_rdy), .running(s_run), .layer(s_layer),
        .adm_done(s_adm), .tok_start(s_tok), .fault(s_fault));
    // ---- merge: the sequencer's own writes only after its init stream.  The init's last write and cal_ready rise on the
    // same edge, so "after init" = cal_ready now AND one edge ago (a reload drops cal_ready with its first init write).
    reg rdy_q, adm_act, btx_seen, brx_seen;
    reg f_col, f_run, f_stale, f_early;      // fault cause (bench observability; `fault` is their OR with the sequencer's)
    wire s_we = (MUT == 1) ? 1'b0 : ((s_tx || s_rx) && s_rdy && rdy_q);
    wire b_we = b_tx_q || b_rx_q;
    wire b_base = b_we && (b_addr_q == 6'b100000);
    wire n_col = b_we && s_we;
    wire n_run = b_we && (s_run || adm_act);
    wire n_stale = b_base && (b_tx_q ? (b_data_q != D2D_CAL_K_TX_SEG2) : (b_data_q != D2D_CAL_K_RX_SEG2));
    wire n_early = s_cs && !(btx_seen && brx_seen);
    always @(posedge ck or negedge rl) begin
        if (!rl) begin
            cfg_tx_we <= 0; cfg_rx_we <= 0; cfg_addr <= 0; cfg_data <= 0;
            cal_start <= 0; cal_seg <= 0; cal_ready <= 0; running <= 0; layer <= 0; adm_done <= 0; tok_start <= 0;
            rdy_q <= 0; adm_act <= 0; btx_seen <= 0; brx_seen <= 0;
            f_col <= 0; f_run <= 0; f_stale <= 0; f_early <= 0; fault <= 0;
        end else begin
            cal_start <= s_cs; cal_seg <= s_seg; cal_ready <= s_rdy; running <= s_run; layer <= s_layer;
            adm_done <= s_adm; tok_start <= s_tok;
            rdy_q <= s_rdy;
            if (b_we) begin
                cfg_tx_we <= b_tx_q; cfg_rx_we <= b_rx_q; cfg_addr <= b_addr_q; cfg_data <= b_data_q;
            end else begin
                cfg_tx_we <= s_we && s_tx; cfg_rx_we <= s_we && s_rx;
                if (s_we) begin cfg_addr <= s_addr; cfg_data <= s_data; end
            end
            // admission run: from its start (layer 63) until adm_done; the token programme is the sequencer's `running`
            if (s_cs && s_seg && s_layer == 6'h3f) adm_act <= 1'b1;
            else if (s_adm || halt_q) adm_act <= 1'b0;
            if (reload_q) begin btx_seen <= 1'b0; brx_seen <= 1'b0; end
            else begin
                if (b_base && b_tx_q) btx_seen <= 1'b1;
                if (b_base && b_rx_q) brx_seen <= 1'b1;
            end
            if (n_col) f_col <= 1'b1;
            if (n_run) f_run <= 1'b1;
            if (n_stale) f_stale <= 1'b1;
            if (n_early) f_early <= 1'b1;
            fault <= fault || s_fault || n_col || n_run || n_stale || n_early;
        end
    end
endmodule

module qkd_host_ctl_service_pins #(parameter WDOG=1<<22,ENABLE_SERVICE=0,MUT=0,MU=0)(
 input wire ck,rst_n,sys_ready,pb_fault,input wire[2:0]die_id,
 input wire[60:0]req,input wire[142:0]pr,input wire[743:0]tk,
 input wire service_abort,service_ready,begin_block,epoch_fault,input wire[7:0]service_ready8,
 output wire[181:0]hc,output wire[119:0]res
);
 reg ready_q,pb_q,abort_q,service_q,block_q,epoch_fault_q;reg[60:0]req_q;reg[142:0]pr_q;reg[743:0]tk_q;reg[2:0]role_q;
 reg[7:0]services_q,faults_q;
 integer i;
 always @(posedge ck or negedge rst_n)if(!rst_n)begin
 ready_q<=0;block_q<=0;epoch_fault_q<=0;req_q<=0;pr_q<=0;tk_q<=0;pb_q<=0;abort_q<=0;service_q<=0;role_q<=0;services_q<=0;faults_q<=0;
 end else begin
 epoch_fault_q<=epoch_fault;req_q<=req;pr_q<=pr;tk_q<=tk;block_q<=begin_block;ready_q<=sys_ready;pb_q<=pb_fault;abort_q<=service_abort;service_q<=service_ready;
 role_q<=die_id;services_q<=service_ready8;
 for(i=0;i<8;i=i+1)faults_q[i]<=tk[93*i+88];
 end
 qkd_host_ctl #(.ND(8),.WDOG(WDOG),.MU(MU))u_core(.ck(ck),.rst_n(rst_n),
 .ready(ready_q&&!pb_q&&role_q==0&&(MUT==1||(!abort_q&&!epoch_fault_q&&service_q&&!(|faults_q)))&&(!ENABLE_SERVICE||(MUT==2)||((&services_q)&&!block_q))),
 .req(req_q),.pr(pr_q),.tk(tk_q),.hc(hc),.res(res));
endmodule

module qkd_host_rx_class_admission #(parameter integer MUT=0,STRAPPED=0,IR_REPL=0)(
 input wire ck,rst_n,input wire[2:0]die_id,input wire rx_v,input wire[527:0]rx_d,output wire rx_cr,
 input wire native_reserved,ownership_valid,
 output reg host_v,output reg[511:0]host_d,input wire host_cr,
 output wire ctrl_v,output wire[511:0]ctrl_d,input wire ctrl_cr,
 output reg ing_v,output reg[1:0]ing_cls,output reg[511:0]ing_d,input wire[4:0]ing_crn,
 output wire[23:0]credit_return,peer_credit,output wire fault,
 output reg admission_open,launch_quiet,output wire deferred
);
 wire hv,iv,base_fault;wire[511:0]hd,id;wire[1:0]ic;
 reg reserved_q,valid_q;reg[511:0]hq[0:3];reg[513:0]iq[0:15];
 reg[1:0]hw,hr;reg[3:0]iw,ir;reg[2:0]hn,hcredits;reg[4:0]in_count,icredits;
 reg hcq;reg[4:0]icq;reg queue_fault;
 wire permit=(MUT==1)||(!reserved_q&&valid_q);
 wire hp=permit&&!fault&&hn!=0&&hcredits!=0;
 wire ip=permit&&!fault&&in_count!=0&&icredits!=0;
 assign fault=base_fault|queue_fault;
 assign deferred=hn!=0||in_count!=0;
 qkd_host_rx_class #(.MUT(0),.STRAPPED(STRAPPED))u_rx(
  .ck(ck),.rst_n(rst_n),.die_id(die_id),.rx_v(rx_v),.rx_d(rx_d),.rx_cr(rx_cr),
  .host_v(hv),.host_d(hd),.host_cr(host_cr),.ctrl_v(ctrl_v),.ctrl_d(ctrl_d),.ctrl_cr(ctrl_cr),
  .ing_v(iv),.ing_cls(ic),.ing_d(id),.ing_crn(ing_crn),
  .credit_return(credit_return),.peer_credit(peer_credit),.fault(base_fault));
 always @(posedge ck)begin
  if(hv&&hn<4)hq[hw]<=hd;
  if(iv&&in_count<16)iq[iw]<={ic,id};
  if(hp)host_d<=hq[hr];
  if(IR_REPL==0)begin if(ip){ing_cls,ing_d}<=iq[ir];end
 end
 generate if(IR_REPL!=0)begin:g_irr
  localparam integer NS=9; // ceil(514/64)
  (* keep="true",dont_touch="true" *) reg[4*NS-1:0]irr;
  genvar s;
  for(s=0;s<NS;s=s+1)begin:g_s
   wire[3:0]a=irr[4*s+:4];wire[513:0]w=iq[a];
   if(s<8)begin:g_d always @(posedge ck)if(ip)ing_d[s*64+:64]<=w[s*64+:64];end
   else begin:g_c always @(posedge ck)if(ip)ing_cls<=w[513:512];end
   always @(posedge ck or negedge rst_n)
    if(!rst_n)irr[4*s+:4]<=0;
`ifdef QKD_IRR_MUTANT
    else if(ip)irr[4*s+:4]<=(s==4)?irr[4*s+:4]+2'd2:irr[4*s+:4]+1'b1;
`else
    else if(ip)irr[4*s+:4]<=irr[4*s+:4]+1'b1;
`endif
  end
 end endgenerate
 always @(posedge ck or negedge rst_n)begin
  if(!rst_n)begin reserved_q<=1;valid_q<=0;admission_open<=0;launch_quiet<=0;
   hw<=0;hr<=0;iw<=0;ir<=0;hn<=0;in_count<=0;hcredits<=4;icredits<=16;
   hcq<=0;icq<=0;host_v<=0;ing_v<=0;queue_fault<=0;
  end else begin
   reserved_q<=native_reserved;valid_q<=ownership_valid;hcq<=host_cr;icq<=ing_crn;
   admission_open<=permit&&!fault;host_v<=hp;ing_v<=ip;
   // Deferred words have not entered the downstream HOST path. This signal
   // observes launches, not a claim that all downstream work has drained.
   launch_quiet<=!hp&&!ip&&!host_v&&!ing_v&&!fault;
   if(hv&&hn==4&&!hp)queue_fault<=1;
   if(iv&&in_count==16&&!ip)queue_fault<=1;
   if(hv)hw<=hw+1'b1;if(hp)hr<=hr+1'b1;
   if(iv)iw<=iw+1'b1;if(ip)ir<=ir+1'b1;
   case({hv,hp})2'b10:hn<=hn+1'b1;2'b01:hn<=hn-1'b1;default:;endcase
   case({iv,ip})2'b10:in_count<=in_count+1'b1;2'b01:in_count<=in_count-1'b1;default:;endcase
   if({1'b0,hcredits}+4'(hcq)-4'(hp)>4)queue_fault<=1;
   else hcredits<=hcredits+3'(hcq)-3'(hp);
   if({1'b0,icredits}+6'(icq)-6'(ip)>16)queue_fault<=1;
   else icredits<=icredits+icq-5'(ip);
  end
 end
endmodule

module qkd_host_service_guard #(parameter SETTLE=4,MUT=0)(
 input wire ck_guard,rst_n,input wire[24:0]raw_faults,
 input wire[2:0]die_id,input wire[7:0]physical_faults,transport_faults,
 input wire accepted_ing_v,input wire[1:0]accepted_ing_cls,
 input wire[15:0]accepted_ing_header,input wire done_v,input wire[63:0]done_d,
 input wire boot_barrier_v,input wire[31:0]boot_barrier_target,
 input wire begin_v,input wire[15:0]begin_epoch,
 input wire pending_advertised,input wire[15:0]pending_epoch,
 input wire[92:0]local_tk,
 output reg[92:0]guarded_tk,output reg abort,service_ready,
 output reg[15:0]service_epoch,output reg[25:0]diag_raw,
 output reg[31:0]status,output reg[3:0]groups,
 output reg[7:0]physical_diag,transport_diag,
 input wire service_protocol_fault
);
 (* ASYNC_REG="TRUE" *)reg[24:0]fm,fs;
 reg protocol_pin_q;reg[2:0]role_q,role;reg role_valid,role_sampled;
 reg[7:0]pf_q,tf_q;reg[92:0]tk_q;
 reg iv,dv,bv,ev,av;reg[1:0]ic;reg[15:0]ih,ep,ap;
 reg[63:0]dd;reg[31:0]bt;
 always @(posedge ck_guard or negedge rst_n)if(!rst_n)begin
 protocol_pin_q<=0;fm<=0;fs<=0;role_sampled<=0;role_q<=0;pf_q<=0;tf_q<=0;tk_q<=0;
 iv<=0;dv<=0;bv<=0;ev<=0;av<=0;ic<=0;ih<=0;ep<=0;ap<=0;dd<=0;bt<=0;
 end else begin
 protocol_pin_q<=service_protocol_fault;fm<=raw_faults;fs<=fm;role_sampled<=1;role_q<=die_id;pf_q<=physical_faults;tf_q<=transport_faults;tk_q<=local_tk;
 iv<=accepted_ing_v;ic<=accepted_ing_cls;ih<=accepted_ing_header;
 dv<=done_v;dd<=done_d;bv<=boot_barrier_v;bt<=boot_barrier_target;
 ev<=begin_v;ep<=begin_epoch;av<=pending_advertised;ap<=pending_epoch;
 end
 reg[24:0]sticky;reg protocol_fault,wait_advert,epoch_dirty;
 reg[31:0]activity_gen,activity_closed,nadmit,nclosed,last_done,last_barrier;
 reg[7:0]quiet;
 wire fp=iv&&ic==1&&ih[7];wire np=iv&&ic==1&&!ih[7];
 wire mp=iv&&ic==0&&ih[7:0]==2;
 wire activity_admit=iv&&!mp;
 // This service candidate requires a genuine ordered BOOT_END for ALL ingest
 // activity. DONE never establishes payload ownership or closes readiness.
 wire unfenced_admit=np||(iv&&ic==0&&!mp)||(iv&&ic==2&&fc==0);
 wire ftv,mtv;wire[7:0]ft;wire[63:0]mt;
 wire[7:0]fc,mc;wire fo,fu,mo,mu;
 // Completion staging absorbs the four-edge bank prefetch startup.
 reg[39:0]dq[0:7];reg[31:0]bq[0:7];reg[2:0]dw,dr,bw,br;
 reg[3:0]dc,bc;
 wire dt=dc!=0&&ftv;wire mb=bc!=0&&mtv;
 wire dp=dv&&dd[63:56]==1&&dd[55:48]==0&&dd[39:32]==0;
 wire dbad=dv&&!dp;
 wire dop=dp&&(dc<8||dt);wire bop=bv&&(bc<8||mb);
 qkd_host_guard_fifo #(.W(8))fenced(ck_guard,rst_n,fp,ih[15:8],dt,ftv,ft,fc,fo,fu);
 qkd_host_guard_fifo #(.W(64))markers(ck_guard,rst_n,mp,{activity_gen,nadmit},mb,mtv,mt,mc,mo,mu);
 wire internal_bad=protocol_pin_q||fo||mo||dbad||(dp&&!dop)||(bv&&!bop)||
 (dc!=0&&fc==0&&!fp)||(bc!=0&&mc==0&&!mp)||
 (dt&&((MUT!=4&&dq[dr][39:32]!=ft)||dq[dr][31:0]<last_done))||
 (mb&&(bq[br]<last_barrier||mt[63:32]>activity_gen||mt[31:0]>nadmit))||
 (role_valid&&role_q!=role)||(activity_admit&&activity_gen==32'hffffffff)||(unfenced_admit&&nadmit==32'hffffffff)||
 (ev&&(ep<=service_epoch||wait_advert||fc!=0||mc!=0||nadmit!=nclosed||activity_gen!=activity_closed));
 wire[24:0]next_sticky=sticky|((MUT==1)?25'b0:fs);
 wire bad=protocol_fault||internal_bad||(|next_sticky);
 wire clean=(MUT==3)||(!epoch_dirty&&(fc==0)&&(mc==0)&&(dc==0)&&(bc==0)&&(nadmit==nclosed)&&((MUT==5)||(activity_gen==activity_closed)));
 wire activity=iv||dv||bv||ev||dt||mb;
 wire[3:0]g={ (|next_sticky[19:14]),(|next_sticky[13:12]),
 ((|next_sticky[11:6])||(|next_sticky[24:20])),(|next_sticky[5:0])};
 always @(posedge ck_guard or negedge rst_n)if(!rst_n)begin
 role<=0;role_valid<=0;sticky<=0;protocol_fault<=0;wait_advert<=0;epoch_dirty<=0;
 activity_gen<=0;activity_closed<=0;nadmit<=0;nclosed<=0;last_done<=0;last_barrier<=0;quiet<=0;
 dw<=0;dr<=0;bw<=0;br<=0;dc<=0;bc<=0;
 guarded_tk<=0;abort<=0;service_ready<=0;service_epoch<=0;diag_raw<=0;
 status<=0;groups<=0;physical_diag<=0;transport_diag<=0;
 end else begin
 if(!role_valid&&role_sampled)begin role<=role_q;role_valid<=1;end
 sticky<=next_sticky;protocol_fault<=protocol_fault||internal_bad;
 if(activity_admit)activity_gen<=activity_gen+1'b1;if(unfenced_admit)nadmit<=nadmit+1'b1;
 if(dop)begin dq[dw]<={dd[47:40],dd[31:0]};dw<=dw+1'b1;end
 if(bop)begin bq[bw]<=bt;bw<=bw+1'b1;end
 if(dt)begin dr<=dr+1'b1;last_done<=dq[dr][31:0];end
 if(mb)begin br<=br+1'b1;nclosed<=mt[31:0];last_barrier<=bq[br];
 if(mt[63:32]>activity_closed)activity_closed<=mt[63:32];end
 case({dop,dt})2'b10:dc<=dc+1'b1;2'b01:dc<=dc-1'b1;endcase
 case({bop,mb})2'b10:bc<=bc+1'b1;2'b01:bc<=bc-1'b1;endcase
 if(ev)begin service_epoch<=ep;wait_advert<=1;epoch_dirty<=1;end
 else if(mb)epoch_dirty<=0;
 if(!ev&&iv&&service_ready)wait_advert<=1;
 else if(!ev&&av&&ap==service_epoch)wait_advert<=0;
 if(activity||!clean||bad||wait_advert)quiet<=0;
 else if(quiet<SETTLE)quiet<=quiet+1'b1;
